candidates.raw:
    adcs_quat_t qa, qb, qa_conj, q_rel;
    double w_abs, c;
    adcs_status_t st;

    if ((a == NULL) || (b == NULL) || (distance_rad == NULL)) {
        return ADCS_E_NULL;
    }

    st = adcs_quat_normalize(a, &qa);
    if (st != ADCS_OK) {
        *distance_rad = INFINITY;
        return ADCS_E_DEGENERATE;
    }
    st = adcs_quat_normalize(b, &qb);
    if (st != ADCS_OK) {
        *distance_rad = INFINITY;
        return ADCS_E_DEGENERATE;
    }

    qa_conj = adcs_quat_conjugate(&qa);
    q_rel = adcs_quat_multiply(&qb, &qa_conj);

    w_abs = fabs(q_rel.w);
    c = ADCS_CLAMP(w_abs, 0.0, 1.0);

    *distance_rad = 2.0 * acos(c);

    return ADCS_OK;
}

